)),const SizedBox(height:8),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('آخر: ${last.toStringAsFixed(1)}%',style:const TextStyle(color:_cyan,fontWeight:FontWeight.bold)),Text('تغير: ${trend>=0?'+':''}${trend.toStringAsFixed(1)}%',style:TextStyle(color:directionColor,fontWeight:FontWeight.bold))])])),const SizedBox(height:12),Row(children:[Expanded(child:_Metric(title:'المتوسط',value:'${avg.toStringAsFixed(1)}%',color:_cyan)),const SizedBox(width:9),Expanded(child:_Metric(title:'القمة',value:'${peak.toStringAsFixed(1)}%',color:Colors.amberAccent)),const SizedBox(width:9),Expanded(child:_Metric(title:'عدد العينات',value:'${values.length}',color:Colors.greenAccent))]),const SizedBox(height:12),Container(padding:const EdgeInsets.all(15),decoration:_decoration(),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('المؤشر الحقيقي',textAlign:TextAlign.right,style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('المؤشر يتحرك من القيم الفعلية المحفوظة من ESP32 ويعرض اتجاه تغيّر الإشارة فقط. لا يمثل بوصلة أو اتجاهًا جغرافيًا ما لم يرسل الجهاز حساس اتجاه/بوصلة.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60,height:1.55))]))]))))])));}}
