class _RadarDecoration extends CustomPainter{@override void paint(Canvas c,Size s){final center=Offset(s.width/2,s.height/2);final r=math.min(s.width,s.height)*.38;final p=Paint()..style=PaintingStyle.stroke..strokeWidth=1..color=_cyan.withValues(alpha:.13);for(int i=1;i<=3;i++)c.drawCircle(center,r*i/3,p);c.drawLine(Offset(center.dx-r,center.dy),Offset(center.dx+r,center.dy),p);c.drawLine(Offset(center.dx,center.dy-r),Offset(center.dx,center.dy+r),p);}@override bool shouldRepaint(covariant _RadarDecoration oldDelegate)=>false;}
class _AnalysisChart extends CustomPainter{_AnalysisChart(this.values);final List<double> values;@override void paint(Canvas c,Size s){final grid=Paint()..color=_line..strokeWidth=1;for(int i=0;i<=4;i++){final y=s.height*i/4;c.drawLine(Offset(0,y),Offset(s.width,y),grid);}if(values.length<2)return;final path=Path();for(int i=0;i<values.length;i++){final x=s.width*i/(values.length-1);final y=s.height*(1-values[i].clamp(0,100)/100);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,Paint()..style=PaintingStyle.stroke..strokeWidth=4..strokeCap=StrokeCap.round..color=_cyan);final last=values.last;final ly=s.height*(1-last.clamp(0,100)/100);c.drawLine(Offset(s.width-34,ly),Offset(s.width,ly),Paint()..color=Colors.greenAccent..strokeWidth=3);c.drawCircle(Offset(s.width-4,ly),6,Paint()..color=Colors.white);}@override bool shouldRepaint(covariant _AnalysisChart oldDelegate)=>oldDelegate.values!=values;}
